const crypto = require('crypto');
const express = require('express');
const multer = require('multer');
const { MongoClient, ObjectId } = require('mongodb');

const app = express();
const upload = multer({ dest: '/tmp/uploads/' });

const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32);
const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';

class SignatureCache {
  constructor(maxAge = 300000) {
    this.entries = new Map();
    this.maxAge = maxAge;
  }

  has(key) {
    const entry = this.entries.get(key);
    if (!entry) return false;
    if (Date.now() - entry.timestamp > this.maxAge) {
      this.entries.delete(key);
      return false;
    }
    return true;
  }

  add(key) {
    this.entries.set(key, { timestamp: Date.now() });
  }

  prune() {
    const now = Date.now();
    for (const [key, entry] of this.entries) {
      if (now - entry.timestamp > this.maxAge) {
        this.entries.delete(key);
      }
    }
  }
}

const signatureCache = new SignatureCache(300000);
setInterval(() => signatureCache.prune(), 60000);

function computeSignature(payload, timestamp, nonce) {
  const message = `${timestamp}:${nonce}:${JSON.stringify(payload)}`;
  return crypto.createHmac('sha256', HMAC_SECRET).update(message).digest('hex');
}

function verifyRequestSignature(req) {
  const signature = req.headers['x-signature'];
  const timestamp = req.headers['x-timestamp'];
  const nonce = req.headers['x-nonce'];

  if (!signature || !timestamp || !nonce) {
    return { valid: false, reason: 'Missing signature headers' };
  }

  const requestTime = parseInt(timestamp, 10);
  const now = Date.now();
  if (Math.abs(now - requestTime) > 300000) {
    return { valid: false, reason: 'Request timestamp expired' };
  }

  const cacheKey = `${nonce}:${timestamp}`;
  if (signatureCache.has(cacheKey)) {
    return { valid: false, reason: 'Nonce already used' };
  }

  const expectedSig = computeSignature(req.body, timestamp, nonce);
  const sigBuffer = Buffer.from(signature, 'hex');
  const expectedBuffer = Buffer.from(expectedSig, 'hex');

  if (sigBuffer.length !== expectedBuffer.length) {
    return { valid: false, reason: 'Invalid signature' };
  }

  if (!crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
    return { valid: false, reason: 'Invalid signature' };
  }

  signatureCache.add(cacheKey);
  return { valid: true };
}

async function processUploadMetadata(db, metadata, fileInfo) {
  const collection = db.collection('uploads');
  const doc = {
    filename: fileInfo.originalname,
    path: fileInfo.path,
    size: fileInfo.size,
    uploadedBy: metadata.userId,
    tags: metadata.tags || [],
    processedAt: new Date(),
    checksum: metadata.checksum
  };
  return collection.insertOne(doc);
}

app.post('/api/upload', upload.single('file'), express.json(), async (req, res) => {
  try {
    const verification = verifyRequestSignature(req);
    if (!verification.valid) {
      return res.status(401).json({ error: verification.reason });
    }

    if (!req.file) {
      return res.status(400).json({ error: 'No file provided' });
    }

    const client = await MongoClient.connect(MONGO_URI);
    const db = client.db('filestore');

    const result = await processUploadMetadata(db, req.body, req.file);
    await client.close();

    return res.status(200).json({ id: result.insertedId, status: 'processed' });
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

app.post('/api/batch-upload', express.json(), async (req, res) => {
  try {
    const verification = verifyRequestSignature(req);
    if (!verification.valid) {
      return res.status(401).json({ error: verification.reason });
    }

    const { operations } = req.body;
    if (!Array.isArray(operations)) {
      return res.status(400).json({ error: 'Invalid operations format' });
    }

    const client = await MongoClient.connect(MONGO_URI);
    const db = client.db('filestore');
    const collection = db.collection('uploads');

    const results = [];
    for (const op of operations) {
      if (op.action === 'update') {
        const filter = { _id: new ObjectId(op.id) };
        const update = { $set: op.fields };
        const r = await collection.updateOne(filter, update);
        results.push({ id: op.id, modified: r.modifiedCount });
      } else if (op.action === 'delete') {
        const filter = { _id: new ObjectId(op.id) };
        const r = await collection.deleteOne(filter);
        results.push({ id: op.id, deleted: r.deletedCount });
      }
    }

    await client.close();
    return res.status(200).json({ results });
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = app;
